-- EcoCiclo: isolated project, ownership and all authoritative transitions enforced in PostgreSQL.
create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to anon, authenticated;
create table public.profiles(id uuid primary key references auth.users on delete cascade,display_name text not null check(length(display_name) between 2 and 120),avatar_path text,bio text not null default '' check(length(bio)<=500),city text not null default '' check(length(city)<=100),created_at timestamptz not null default now());
create table public.user_roles(user_id uuid not null references auth.users on delete cascade,role text not null check(role in ('user','technician','admin','recycler')),primary key(user_id,role));
create or replace function private.has_role(wanted text) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from public.user_roles where user_id=(select auth.uid()) and role=wanted)$$;
revoke all on function private.has_role(text) from public;
grant execute on function private.has_role(text) to anon,authenticated;
create table public.devices(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users,type text not null check(type in ('Computador','Notebook','Celular','Televisor','Monitor','Impressora','Periférico','Outro')),brand text not null check(length(brand) between 1 and 80),model text not null default '' check(length(model)<=100),defect text not null check(length(defect) between 10 and 2000),powers_on text not null default 'Não sei' check(powers_on in ('Sim','Não','Não sei','Liga, mas apresenta falhas')),physical_condition text not null default '' check(length(physical_condition)<=1000),unused_since text not null default '' check(length(unused_since)<=80),status text not null default 'draft' check(status in ('draft','awaiting_technical','in_review','approved','rejected','recycling')),created_at timestamptz not null default now());
create index devices_owner_idx on public.devices(owner_id,created_at desc);
create index devices_status_idx on public.devices(status,created_at);
create table public.device_images(id uuid primary key default gen_random_uuid(),device_id uuid not null references public.devices on delete cascade,owner_id uuid not null references auth.users,storage_path text not null unique check(length(storage_path)<=400),created_at timestamptz not null default now());
create index device_images_device_idx on public.device_images(device_id);
create table public.ai_analyses(id uuid primary key default gen_random_uuid(),device_id uuid not null references public.devices,owner_id uuid not null references auth.users,status text not null check(status in ('pending','completed','failed','unavailable')),result jsonb,confidence numeric check(confidence between 0 and 1),provider text,created_at timestamptz not null default now());
create index ai_device_idx on public.ai_analyses(device_id,created_at desc);
create table public.technical_evaluations(id uuid primary key default gen_random_uuid(),device_id uuid not null references public.devices,technician_id uuid not null references auth.users,component_name text not null check(length(component_name) between 2 and 160),procedure text not null check(length(procedure) between 10 and 4000),result text not null check(result in ('approved','rejected','in_review')),notes text not null default '' check(length(notes)<=4000),created_at timestamptz not null default now());
create index evaluations_device_idx on public.technical_evaluations(device_id);
create index evaluations_technician_idx on public.technical_evaluations(technician_id);
create table public.components(id uuid primary key default gen_random_uuid(),device_id uuid not null references public.devices,evaluation_id uuid not null unique references public.technical_evaluations,name text not null check(length(name) between 2 and 160),category text not null check(category in ('Memórias RAM','Armazenamento','Processadores','Placas de vídeo','Placas-mãe','Notebooks','Outros')),brand text not null default '',model text not null default '',status text not null check(status in ('approved','rejected','in_review')),condition text not null check(condition in ('Excelente','Bom','Marcas de uso')),specifications jsonb not null default '{}',mass_grams numeric(12,3) not null default 0 check(mass_grams>=0),created_at timestamptz not null default now());
create index components_device_idx on public.components(device_id);
create table public.component_compatibility(id uuid primary key default gen_random_uuid(),component_id uuid not null references public.components on delete cascade,equipment_model text not null,verified_by uuid not null references auth.users,evidence text not null check(length(evidence)>=10),created_at timestamptz not null default now());
create index compatibility_component_idx on public.component_compatibility(component_id);
create table public.product_listings(id uuid primary key default gen_random_uuid(),component_id uuid not null unique references public.components,seller_id uuid not null references auth.users,seller_name text not null,title text not null,category text not null,brand text not null default '',model text not null default '',description text not null default '',price numeric(12,2) not null check(price>0 and price<=100000),quantity integer not null default 1 check(quantity between 0 and 1),condition text not null,city text not null default '' check(length(city)<=100),specifications jsonb not null default '{}',test_procedure text not null,tested_at timestamptz not null,status text not null default 'published' check(status in ('published','paused','removed')),created_at timestamptz not null default now());
create index listings_catalog_idx on public.product_listings(category,created_at desc) where status='published' and quantity>0;
create index listings_seller_idx on public.product_listings(seller_id);
create table public.favorites(user_id uuid not null references auth.users on delete cascade,listing_id uuid not null references public.product_listings on delete cascade,created_at timestamptz not null default now(),primary key(user_id,listing_id));
create table public.carts(user_id uuid primary key references auth.users on delete cascade,created_at timestamptz not null default now());
create table public.cart_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,listing_id uuid not null references public.product_listings,quantity integer not null check(quantity between 1 and 99),unique(user_id,listing_id));
create index cart_listing_idx on public.cart_items(listing_id);
create table public.orders(id uuid primary key default gen_random_uuid(),buyer_id uuid not null references auth.users,status text not null default 'pending_confirmation' check(status in ('pending_confirmation','paid','cancelled')),total numeric(12,2) not null check(total>=0),address jsonb not null,created_at timestamptz not null default now());
create index orders_buyer_idx on public.orders(buyer_id,created_at desc);
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,listing_id uuid not null references public.product_listings,seller_id uuid not null references auth.users,title text not null,quantity integer not null check(quantity>0),unit_price numeric(12,2) not null check(unit_price>0));
create index order_items_order_idx on public.order_items(order_id);
create index order_items_seller_idx on public.order_items(seller_id);
create table public.recycling_partners(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users,name text not null check(length(name) between 2 and 180),city text not null check(length(city) between 2 and 100),description text not null default '',active boolean not null default true,created_at timestamptz not null default now());
create index recycling_partner_user_idx on public.recycling_partners(user_id);
create table public.recycling_requests(id uuid primary key default gen_random_uuid(),device_id uuid not null unique references public.devices,owner_id uuid not null references auth.users,partner_id uuid references public.recycling_partners,notes text not null default '' check(length(notes)<=2000),status text not null default 'awaiting' check(status in ('awaiting','requested','received','confirmed')),created_at timestamptz not null default now());
create index recycling_requests_owner_idx on public.recycling_requests(owner_id);
create index recycling_requests_partner_idx on public.recycling_requests(partner_id);
create table public.recycling_records(id uuid primary key default gen_random_uuid(),request_id uuid not null unique references public.recycling_requests,partner_id uuid not null references public.recycling_partners,recorded_by uuid not null references auth.users,mass_grams numeric(12,3) not null check(mass_grams>0),proof_path text not null check(length(proof_path)>8),confirmed_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,title text not null,body text not null,read_at timestamptz,created_at timestamptz not null default now());
create index notifications_user_idx on public.notifications(user_id,created_at desc);
create table public.reports(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users,listing_id uuid references public.product_listings,reason text not null check(length(reason) between 5 and 2000),status text not null default 'pending' check(status in ('pending','reviewed')),created_at timestamptz not null default now());
create index reports_user_idx on public.reports(user_id);
create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid,table_name text not null,record_id text,action text not null,created_at timestamptz not null default now());
create or replace function private.new_account() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,display_name) values(new.id,left(coalesce(nullif(trim(new.raw_user_meta_data->>'display_name'),''),'Novo usuário'),120));insert into public.user_roles values(new.id,'user');insert into public.carts(user_id) values(new.id);return new;end$$;
revoke all on function private.new_account() from public;
create trigger on_ecociclo_signup after insert on auth.users for each row execute function private.new_account();
create or replace function private.audit_event() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.audit_logs(actor_id,table_name,record_id,action) values(auth.uid(),tg_table_name,coalesce(to_jsonb(new)->>'id',to_jsonb(old)->>'id',to_jsonb(new)->>'user_id'),tg_op);if tg_op='DELETE' then return old;end if;return new;end$$;
revoke all on function private.audit_event() from public;
create or replace function private.notify_device() returns trigger language plpgsql security definer set search_path='' as $$begin if new.status is distinct from old.status then insert into public.notifications(user_id,title,body) values(new.owner_id,'Seu equipamento avançou no ciclo','O status de '||new.brand||' '||new.model||' foi atualizado. Acompanhe os detalhes no painel.');end if;return new;end$$;
revoke all on function private.notify_device() from public;
create trigger device_status_notification after update of status on public.devices for each row execute function private.notify_device();
do $$declare t text;begin foreach t in array array['profiles','user_roles','devices','device_images','ai_analyses','technical_evaluations','components','component_compatibility','product_listings','favorites','carts','cart_items','orders','order_items','recycling_partners','recycling_requests','recycling_records','notifications','reports','audit_logs'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);end loop;foreach t in array array['user_roles','technical_evaluations','components','product_listings','orders','recycling_records','recycling_partners'] loop execute format('create trigger audit_%I after insert or update or delete on public.%I for each row execute function private.audit_event()',t,t);end loop;end$$;
grant select on public.product_listings,public.component_compatibility,public.recycling_partners to anon;
grant insert,update on public.profiles to authenticated;
grant insert,update,delete on public.devices,public.device_images,public.cart_items,public.favorites to authenticated;
grant insert on public.recycling_requests,public.reports to authenticated;
grant update(read_at) on public.notifications to authenticated;
grant insert,update on public.recycling_partners to authenticated;
grant update(status) on public.product_listings,public.reports to authenticated;
create policy profiles_read on public.profiles for select to authenticated using(id=(select auth.uid()) or private.has_role('admin'));
create policy profiles_update on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy roles_read on public.user_roles for select to authenticated using(user_id=(select auth.uid()) or private.has_role('admin'));
create policy devices_read on public.devices for select to authenticated using(owner_id=(select auth.uid()) or private.has_role('admin') or (private.has_role('technician') and status<>'draft'));
create policy devices_insert on public.devices for insert to authenticated with check(owner_id=(select auth.uid()) and status='draft');
create policy devices_update on public.devices for update to authenticated using(owner_id=(select auth.uid()) and status='draft') with check(owner_id=(select auth.uid()) and status='draft');
create policy devices_delete on public.devices for delete to authenticated using(owner_id=(select auth.uid()) and status='draft');
create policy images_read on public.device_images for select to authenticated using(owner_id=(select auth.uid()) or private.has_role('admin') or (private.has_role('technician') and exists(select 1 from public.devices d where d.id=device_id and d.status<>'draft')));
create policy images_insert on public.device_images for insert to authenticated with check(owner_id=(select auth.uid()) and storage_path like (select auth.uid())::text||'/'||device_id::text||'/%' and exists(select 1 from public.devices d where d.id=device_id and d.owner_id=(select auth.uid()) and d.status='draft') and exists(select 1 from storage.objects o where o.bucket_id='device-images' and o.name=storage_path));
create policy images_delete on public.device_images for delete to authenticated using(owner_id=(select auth.uid()) and exists(select 1 from public.devices d where d.id=device_id and d.status='draft'));
create policy ai_read on public.ai_analyses for select to authenticated using(owner_id=(select auth.uid()) or private.has_role('admin'));
create policy evaluations_read on public.technical_evaluations for select to authenticated using(technician_id=(select auth.uid()) or private.has_role('admin') or exists(select 1 from public.devices d where d.id=device_id and d.owner_id=(select auth.uid())));
create policy components_read on public.components for select to authenticated using(private.has_role('admin') or private.has_role('technician') or exists(select 1 from public.devices d where d.id=device_id and d.owner_id=(select auth.uid())));
create policy compatibility_read on public.component_compatibility for select to anon,authenticated using(exists(select 1 from public.product_listings l where l.component_id=component_compatibility.component_id and l.status='published'));
create policy listings_read on public.product_listings for select to anon,authenticated using(status='published' or seller_id=(select auth.uid()) or private.has_role('admin'));
create policy listings_moderate on public.product_listings for update to authenticated using(private.has_role('admin')) with check(private.has_role('admin'));
create policy favorites_read on public.favorites for select to authenticated using(user_id=(select auth.uid()));
create policy favorites_insert on public.favorites for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.product_listings l where l.id=listing_id and l.status='published'));
create policy favorites_delete on public.favorites for delete to authenticated using(user_id=(select auth.uid()));
create policy carts_read on public.carts for select to authenticated using(user_id=(select auth.uid()));
create policy cart_items_read on public.cart_items for select to authenticated using(user_id=(select auth.uid()));
create policy cart_items_insert on public.cart_items for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.product_listings l where l.id=listing_id and l.status='published' and l.quantity>=cart_items.quantity and l.seller_id<>(select auth.uid())));
create policy cart_items_update on public.cart_items for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()) and exists(select 1 from public.product_listings l where l.id=listing_id and l.status='published' and l.quantity>=cart_items.quantity and l.seller_id<>(select auth.uid())));
create policy cart_items_delete on public.cart_items for delete to authenticated using(user_id=(select auth.uid()));
create policy orders_read on public.orders for select to authenticated using(buyer_id=(select auth.uid()) or private.has_role('admin'));
create policy order_items_read on public.order_items for select to authenticated using(seller_id=(select auth.uid()) or private.has_role('admin') or exists(select 1 from public.orders o where o.id=order_id and o.buyer_id=(select auth.uid())));
create policy partners_read on public.recycling_partners for select to anon,authenticated using(active or private.has_role('admin') or user_id=(select auth.uid()));
create policy partners_insert on public.recycling_partners for insert to authenticated with check(private.has_role('admin'));
create policy partners_update on public.recycling_partners for update to authenticated using(private.has_role('admin')) with check(private.has_role('admin'));
create policy recycling_requests_read on public.recycling_requests for select to authenticated using(owner_id=(select auth.uid()) or private.has_role('admin') or exists(select 1 from public.recycling_partners rp where rp.id=partner_id and rp.user_id=(select auth.uid())));
create policy recycling_requests_insert on public.recycling_requests for insert to authenticated with check(owner_id=(select auth.uid()) and status='awaiting' and exists(select 1 from public.devices d where d.id=device_id and d.owner_id=(select auth.uid()) and d.status<>'draft') and (partner_id is null or exists(select 1 from public.recycling_partners rp where rp.id=partner_id and rp.active)));
create policy recycling_records_read on public.recycling_records for select to authenticated using(private.has_role('admin') or recorded_by=(select auth.uid()) or exists(select 1 from public.recycling_requests rr where rr.id=request_id and rr.owner_id=(select auth.uid())));
create policy notifications_read on public.notifications for select to authenticated using(user_id=(select auth.uid()));
create policy notifications_update on public.notifications for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy reports_read on public.reports for select to authenticated using(user_id=(select auth.uid()) or private.has_role('admin'));
create policy reports_insert on public.reports for insert to authenticated with check(user_id=(select auth.uid()) and status='pending');
create policy reports_update on public.reports for update to authenticated using(private.has_role('admin')) with check(private.has_role('admin'));
create policy audit_read on public.audit_logs for select to authenticated using(private.has_role('admin'));
-- Authority lives in the unexposed private schema; public RPCs are SECURITY INVOKER wrappers.
create function private.submit_device(device_uuid uuid) returns void language plpgsql security definer set search_path='' as $$begin if auth.uid() is null then raise exception 'Entre na sua conta.';end if;if not exists(select 1 from public.device_images where device_id=device_uuid and owner_id=auth.uid()) then raise exception 'Adicione pelo menos uma fotografia.';end if;update public.devices set status='awaiting_technical' where id=device_uuid and owner_id=auth.uid() and status='draft';if not found then raise exception 'Equipamento não encontrado ou já enviado.';end if;end$$;
create function public.submit_device(device_uuid uuid) returns void language sql security invoker set search_path='' as $$select private.submit_device(device_uuid)$$;
create function private.record_evaluation(device_uuid uuid,evaluation_components jsonb) returns void language plpgsql security definer set search_path='' as $$declare item jsonb; ev uuid; passed boolean:=false; dev public.devices; outcome text;begin if not(private.has_role('technician') or private.has_role('admin')) then raise exception 'Apenas técnicos autorizados podem registrar avaliações.';end if;select * into dev from public.devices where id=device_uuid for update;if not found or dev.status not in ('awaiting_technical','in_review') then raise exception 'Solicitação indisponível para avaliação.';end if;if jsonb_typeof(evaluation_components)<>'array' or jsonb_array_length(evaluation_components) not between 1 and 20 then raise exception 'Informe de 1 a 20 componentes.';end if;for item in select * from jsonb_array_elements(evaluation_components) loop outcome:=item->>'result';if outcome not in ('approved','rejected') or length(trim(item->>'procedure'))<10 or length(trim(item->>'name'))<2 then raise exception 'Registre identificação, procedimento e resultado reais para cada peça.';end if;insert into public.technical_evaluations(device_id,technician_id,component_name,procedure,result,notes) values(device_uuid,auth.uid(),item->>'name',item->>'procedure',outcome,coalesce(item->>'notes','')) returning id into ev;insert into public.components(device_id,evaluation_id,name,category,brand,model,status,condition,specifications,mass_grams) values(device_uuid,ev,item->>'name',item->>'category',coalesce(item->>'brand',''),coalesce(item->>'model',''),outcome,item->>'condition',coalesce(item->'specifications','{}'::jsonb),coalesce((item->>'mass_grams')::numeric,0));passed:=passed or outcome='approved';end loop;update public.devices set status=case when passed then 'approved' else 'rejected' end where id=device_uuid;end$$;
create function public.record_evaluation(device_uuid uuid,evaluation_components jsonb) returns void language sql security invoker set search_path='' as $$select private.record_evaluation(device_uuid,evaluation_components)$$;
create function private.request_retest(device_uuid uuid) returns void language plpgsql security definer set search_path='' as $$begin if not(private.has_role('technician') or private.has_role('admin')) then raise exception 'Acesso restrito.';end if;update public.devices set status='in_review' where id=device_uuid and status='awaiting_technical';if not found then raise exception 'Solicitação indisponível.';end if;end$$;
create function public.request_retest(device_uuid uuid) returns void language sql security invoker set search_path='' as $$select private.request_retest(device_uuid)$$;
create function private.publish_component(component_uuid uuid,listing_price numeric,listing_quantity integer,listing_city text) returns uuid language plpgsql security definer set search_path='' as $$declare c public.components;ev public.technical_evaluations;owner uuid;name text;lid uuid;begin if auth.uid() is null then raise exception 'Entre na sua conta.';end if;select * into c from public.components where id=component_uuid and status='approved' for update;if not found then raise exception 'Apenas componentes aprovados podem ser publicados.';end if;select owner_id into owner from public.devices where id=c.device_id;if owner<>auth.uid() and not private.has_role('admin') then raise exception 'Você não é o responsável pelo componente.';end if;if listing_quantity<>1 then raise exception 'Cada avaliação corresponde a uma peça física.';end if;select * into ev from public.technical_evaluations where id=c.evaluation_id and result='approved';if not found then raise exception 'Avaliação aprovada não encontrada.';end if;select display_name into name from public.profiles where id=owner;insert into public.product_listings(component_id,seller_id,seller_name,title,category,brand,model,description,price,quantity,condition,city,specifications,test_procedure,tested_at) values(c.id,owner,name,c.name,c.category,c.brand,c.model,ev.notes,listing_price,1,c.condition,listing_city,c.specifications,ev.procedure,ev.created_at) returning id into lid;return lid;end$$;
create function public.publish_component(component_uuid uuid,listing_price numeric,listing_quantity integer,listing_city text) returns uuid language sql security invoker set search_path='' as $$select private.publish_component(component_uuid,listing_price,listing_quantity,listing_city)$$;
create function private.checkout_cart(delivery_address jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare uid uuid:=auth.uid(); oid uuid:=gen_random_uuid(); item record;total_amount numeric:=0;begin if uid is null then raise exception 'Entre na sua conta.';end if;perform pg_advisory_xact_lock(hashtextextended(uid::text,0));if coalesce(length(trim(delivery_address->>'recipient')),0)<2 or coalesce(length(trim(delivery_address->>'street')),0)<5 or coalesce(length(trim(delivery_address->>'city')),0)<2 or not coalesce(delivery_address->>'postal_code','') ~ '^[0-9]{5}-?[0-9]{3}$' then raise exception 'Preencha um endereço válido.';end if;if not exists(select 1 from public.cart_items where user_id=uid) then raise exception 'Seu carrinho está vazio.';end if;perform l.id from public.product_listings l join public.cart_items ci on ci.listing_id=l.id where ci.user_id=uid order by l.id for update of l;for item in select ci.quantity requested,l.* from public.cart_items ci join public.product_listings l on l.id=ci.listing_id where ci.user_id=uid loop if item.status<>'published' or item.quantity<item.requested or item.seller_id=uid then raise exception 'Um componente ficou indisponível. Atualize seu carrinho.';end if;total_amount:=total_amount+item.price*item.requested;end loop;insert into public.orders(id,buyer_id,total,address) values(oid,uid,total_amount,delivery_address);for item in select ci.quantity requested,l.* from public.cart_items ci join public.product_listings l on l.id=ci.listing_id where ci.user_id=uid loop insert into public.order_items(order_id,listing_id,seller_id,title,quantity,unit_price) values(oid,item.id,item.seller_id,item.title,item.requested,item.price);update public.product_listings set quantity=quantity-item.requested where id=item.id;end loop;delete from public.cart_items where user_id=uid;return oid;end$$;
create function public.checkout_cart(delivery_address jsonb) returns uuid language sql security invoker set search_path='' as $$select private.checkout_cart(delivery_address)$$;
create function private.cancel_order(order_uuid uuid) returns void language plpgsql security definer set search_path='' as $$declare o public.orders;item record;begin if auth.uid() is null then raise exception 'Entre na sua conta.';end if;select * into o from public.orders where id=order_uuid for update;if not found or (o.buyer_id<>auth.uid() and not private.has_role('admin')) then raise exception 'Pedido não encontrado.';end if;if o.status<>'pending_confirmation' then raise exception 'Este pedido não pode ser cancelado automaticamente.';end if;perform l.id from public.product_listings l join public.order_items oi on oi.listing_id=l.id where oi.order_id=order_uuid order by l.id for update of l;for item in select * from public.order_items where order_id=order_uuid loop update public.product_listings set quantity=quantity+item.quantity where id=item.listing_id;end loop;update public.orders set status='cancelled' where id=order_uuid;end$$;
create function public.cancel_order(order_uuid uuid) returns void language sql security invoker set search_path='' as $$select private.cancel_order(order_uuid)$$;
create function private.grant_role(target_user uuid,new_role text,enabled boolean) returns void language plpgsql security definer set search_path='' as $$begin if not private.has_role('admin') then raise exception 'Acesso exclusivo da administração.';end if;if new_role not in ('technician','admin','recycler') then raise exception 'Perfil inválido.';end if;if target_user=auth.uid() and new_role='admin' and not enabled then raise exception 'Não remova seu próprio acesso administrativo.';end if;if enabled then insert into public.user_roles values(target_user,new_role) on conflict do nothing;else delete from public.user_roles where user_id=target_user and role=new_role;end if;end$$;
create function public.grant_role(target_user uuid,new_role text,enabled boolean) returns void language sql security invoker set search_path='' as $$select private.grant_role(target_user,new_role,enabled)$$;
create function private.advance_recycling(request_uuid uuid,new_status text,mass numeric,proof text) returns void language plpgsql security definer set search_path='' as $$declare r public.recycling_requests;partner_user uuid;begin if auth.uid() is null then raise exception 'Entre na sua conta.';end if;select * into r from public.recycling_requests where id=request_uuid for update;if not found then raise exception 'Encaminhamento não encontrado.';end if;select user_id into partner_user from public.recycling_partners where id=r.partner_id;if not private.has_role('admin') and not (private.has_role('recycler') and partner_user=auth.uid()) then raise exception 'Acesso restrito ao parceiro responsável.';end if;if not ((r.status='awaiting' and new_status='requested') or (r.status='requested' and new_status='received') or (r.status='received' and new_status='confirmed')) then raise exception 'Transição de destinação inválida.';end if;if r.partner_id is null then raise exception 'Cadastre e vincule o parceiro antes do encaminhamento.';end if;if new_status='confirmed' then if mass is null or mass<=0 or proof is null or not exists(select 1 from storage.objects where bucket_id='recycling-proofs' and name=proof and (storage.foldername(name))[1]=auth.uid()::text) then raise exception 'Informe a massa e envie um comprovante válido.';end if;insert into public.recycling_records(request_id,partner_id,recorded_by,mass_grams,proof_path) values(r.id,r.partner_id,auth.uid(),mass,proof);end if;update public.recycling_requests set status=new_status where id=r.id;end$$;
create function public.advance_recycling(request_uuid uuid,new_status text,mass numeric default null,proof text default null) returns void language sql security invoker set search_path='' as $$select private.advance_recycling(request_uuid,new_status,mass,proof)$$;
create function private.assign_recycling(request_uuid uuid,partner_uuid uuid) returns void language plpgsql security definer set search_path='' as $$begin if not private.has_role('admin') then raise exception 'Acesso restrito.';end if;if not exists(select 1 from public.recycling_partners where id=partner_uuid and active) then raise exception 'Parceiro inválido.';end if;update public.recycling_requests set partner_id=partner_uuid where id=request_uuid and status='awaiting';if not found then raise exception 'Encaminhamento indisponível.';end if;end$$;
create function public.assign_recycling(request_uuid uuid,partner_uuid uuid) returns void language sql security invoker set search_path='' as $$select private.assign_recycling(request_uuid,partner_uuid)$$;
create function private.impact_metrics() returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('devices',(select count(*) from public.devices where status<>'draft'),'evaluated',(select count(distinct device_id) from public.technical_evaluations),'recovered',(select count(*) from public.components where status='approved'),'sold',(select coalesce(sum(oi.quantity),0) from public.order_items oi join public.orders o on o.id=oi.order_id where o.status='paid'),'reused_kg',(select coalesce(sum(c.mass_grams),0)/1000 from public.components c join public.product_listings l on l.component_id=c.id join public.order_items oi on oi.listing_id=l.id join public.orders o on o.id=oi.order_id where o.status='paid'),'recycled_kg',(select coalesce(sum(mass_grams),0)/1000 from public.recycling_records),'sent_kg',(select coalesce(sum(c.mass_grams),0)/1000 from public.components c where exists(select 1 from public.recycling_requests r where r.device_id=c.device_id and r.status in ('requested','received','confirmed'))),'months',(select coalesce(jsonb_agg(jsonb_build_object('month',to_char(m,'MM/YYYY'),'devices',(select count(*) from public.devices d where d.status<>'draft' and date_trunc('month',d.created_at)=m),'recovered',(select count(*) from public.components c where c.status='approved' and date_trunc('month',c.created_at)=m)) order by m),'[]'::jsonb) from generate_series(date_trunc('month',now())-interval '11 months',date_trunc('month',now()),interval '1 month') m))$$;
create function public.impact_metrics() returns jsonb language sql stable security invoker set search_path='' as $$select private.impact_metrics()$$;
-- Explicit privilege grants: no PUBLIC execution of privileged routines.
revoke all on all functions in schema private from public;
revoke all on all functions in schema public from public;
grant execute on function private.has_role(text),private.impact_metrics(),public.impact_metrics() to anon,authenticated;
grant execute on all functions in schema public to authenticated;
grant execute on function private.submit_device(uuid),private.record_evaluation(uuid,jsonb),private.request_retest(uuid),private.publish_component(uuid,numeric,integer,text),private.checkout_cart(jsonb),private.cancel_order(uuid),private.grant_role(uuid,text,boolean),private.advance_recycling(uuid,text,numeric,text),private.assign_recycling(uuid,uuid) to authenticated;
-- Private storage: access is limited to owners and authorized reviewers.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('device-images','device-images',false,5242880,array['image/jpeg','image/png','image/webp']),('avatars','avatars',false,5242880,array['image/jpeg','image/png','image/webp']),('recycling-proofs','recycling-proofs',false,5242880,array['image/jpeg','image/png','image/webp','application/pdf']);
create policy own_photo_insert on storage.objects for insert to authenticated with check((storage.foldername(name))[1]=(select auth.uid())::text and ((bucket_id='device-images' and exists(select 1 from public.devices d where d.id::text=(storage.foldername(name))[2] and d.owner_id=(select auth.uid()) and d.status='draft') and (select count(*) from public.device_images i where i.device_id::text=(storage.foldername(name))[2])<6) or bucket_id='avatars' or (bucket_id='recycling-proofs' and (private.has_role('admin') or private.has_role('recycler')))));
create policy private_photo_select on storage.objects for select to authenticated using((bucket_id in ('device-images','avatars','recycling-proofs') and (storage.foldername(name))[1]=(select auth.uid())::text) or (bucket_id='device-images' and (private.has_role('admin') or (private.has_role('technician') and exists(select 1 from public.devices d where d.id::text=(storage.foldername(name))[2] and d.status<>'draft')))));
create policy own_photo_delete on storage.objects for delete to authenticated using((storage.foldername(name))[1]=(select auth.uid())::text and (bucket_id='avatars' or (bucket_id='device-images' and exists(select 1 from public.devices d where d.id::text=(storage.foldername(name))[2] and d.status='draft'))));

create function private.enforce_image_limit() returns trigger language plpgsql security invoker set search_path='' as $$begin perform id from public.devices where id=new.device_id and owner_id=auth.uid() for update;if (select count(*) from public.device_images where device_id=new.device_id)>6 then raise exception 'Envie no máximo 6 fotografias por equipamento.';end if;return new;end$$;
revoke all on function private.enforce_image_limit() from public;
create trigger device_photo_limit after insert on public.device_images for each row execute function private.enforce_image_limit();
